    }
  }
}

function compileSegment(segment) {
  if (segment === '**') return null;
  const chars = Array.from(segment);
  const tokens = [];
  let i = 0;
  function character() {
    const value = chars[i++];
    if (value !== '\\') return { value, escaped: false };
    const next = chars[i++];
    if (!escapable.has(next)) throw new Error('Invalid glob escape');
    return { value: next, escaped: true };
  }
  while (i < chars.length) {
    const { value, escaped } = character();
    if (escaped) {
      tokens.push({ type: 'literal', value });
    } else if (value === '*') {
      if (tokens.at(-1)?.type !== 'star') tokens.push({ type: 'star' });
    } else if (value === '?') {
      tokens.push({ type: 'any' });
    } else if (value === '[') {
      const negated = chars[i] === '!' || chars[i] === '^';
      if (negated) i++;
      const members = [];
      if (chars[i] === ']') members.push(character());
      while (i < chars.length && chars[i] !== ']') members.push(character());
      if (i === chars.length) throw new Error('Unclosed glob character class');
      i++;
      const ranges = [];
      for (let j = 0; j < members.length; j++) {
        const start = members[j].value.codePointAt(0);
        if (j + 2 < members.length && members[j + 1].value === '-'
            && !members[j + 1].escaped
            && !(j === 0 && members[j].value === '-' && !members[j].escaped)
            && !(j + 2 === members.length - 1 && members[j + 2].value === '-'
              && !members[j + 2].escaped)) {
          const end = members[j + 2].value.codePointAt(0);
          ranges.push([start, end]);
          j += 2;
        } else {
          ranges.push([start, start]);
        }
      }
      tokens.push({ type: 'class', negated, ranges });
    } else {
      tokens.push({ type: 'literal', value });
    }
  }
