+  const pathSegments = paths.map(path => {
+    const segments = path.split('/');
+    if (seen.has(path) || path.includes('\0')
+        || segments.some(segment => !segment || segment === '.' || segment === '..')) {
+      throw new Error('Invalid or duplicate path');
+    }
+    seen.add(path);
+    return segments.map(segment => Array.from(segment));
+  });
+  // Compile every pattern before matching, including when there are no paths.
+  const compiled = patterns.map(pattern => {
+    const negated = pattern[0] === '!';
+    const body = negated ? pattern.slice(1) : pattern;
+    if (!body) throw new Error('Empty glob pattern body');
+    return { negated, segments: body.split('/').map(compileSegment) };
+  });
+  const selected = [];
+  const decisions = paths.map((path, i) => {
+    let included = false;
+    let pattern = -1;
+    for (let j = 0; j < compiled.length; j++) {
+      if (matchesPath(pathSegments[i], compiled[j].segments)) {
+        included = !compiled[j].negated;
+        pattern = j;
+      }
+    }
+    if (included) selected.push(path);
+    return { path, included, pattern };
+  });
+  return { selected, decisions };
+}
+
+function main() {
+  try {
+    if (process.argv.length !== 3) throw new Error('Usage: node glob-select.js INPUT_JSON_FILE');
+    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
+    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
+      throw new Error('Input must be a JSON object');
+    }
+    const result = selectPaths(input.paths, input.patterns);
+    process.stdout.write(JSON.stringify(result) + '\n');
+  } catch (error) {
+    process.stderr.write(`${error.message}\n`);
+    process.exitCode = 2;
+  }
+}
+
+let isEntryPoint = false;
+if (process.argv[1]) {
+  try {
+    isEntryPoint = realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
+  } catch {
+    // An importing program need not have a filesystem entry point.
+  }
+}
+if (isEntryPoint) main();

