import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { selectPaths } from '../glob-select.js';

test('ordered receipts include unmatched paths and work with frozen inputs', () => {
  assert.deepEqual(selectPaths(Object.freeze(['a.js', 'b.js', 'x/c.js', 'readme']),
    Object.freeze(['**/*.js', '!b.js', 'b.*', '!b.js'])), {
    selected: ['a.js', 'x/c.js'],
    decisions: [
      { path: 'a.js', included: true, pattern: 0 },
      { path: 'b.js', included: false, pattern: 3 },
      { path: 'x/c.js', included: true, pattern: 0 },
      { path: 'readme', included: false, pattern: -1 },
    ],
  });
});

test('globstars consume whole segments, including zero segments', () => {
  const paths = ['a/b', 'a/x/b', 'a/x/y/b', 'a/xb', 'b', 'a'];
  assert.deepEqual(selectPaths(paths, ['a/**/b']).selected, paths.slice(0, 3));
  assert.deepEqual(selectPaths(paths, ['a/**/**']).selected, paths.filter(p => p !== 'b'));
  assert.deepEqual(selectPaths(paths, ['**/b']).selected, [...paths.slice(0, 3), 'b']);
  assert.deepEqual(selectPaths(paths, ['a/***b']).selected, ['a/b', 'a/xb']);
});

test('classes, literals, escapes, and characters do not use regex syntax', () => {
  const cases = [
    [['a', 'b', 'c', 'd'], '[a-c]', ['a', 'b', 'c']],
    [['a', 'b', 'z'], '[!a-b]', ['z']],
    [['a', 'b', 'z'], '[^a-b]', ['z']],
    [[']', 'a', 'b'], '[]a]', [']', 'a']],
    [[']', 'a', 'b'], '[!]]', ['a', 'b']],
    [['-', 'a', 'b'], '[-a]', ['-', 'a']],
    [['-', 'a', 'b'], '[a-]', ['-', 'a']],
    [['-', 'a', 'b', 'z'], '[a\\-z]', ['-', 'a', 'z']],
    [['*', '?', 'x'], '\\*', ['*']],
    [['!x', 'x'], '\\!x', ['!x']],
    [['a+b.(x)', 'abzx'], 'a+b.(x)', ['a+b.(x)']],
    [['é', '😀', 'ab'], '?', ['é', '😀']],
    [['a\\b'], 'a\\\\b', ['a\\b']],
  ];
  for (const [paths, pattern, expected] of cases) {
    assert.deepEqual(selectPaths(paths, [pattern]).selected, expected, pattern);
  }
});

test('validation runs even with an empty opposite array', () => {
  for (const paths of [null, {}, 'a', [1], [''], Array(1), ['a', 'a'],
    ['/a'], ['a/'], ['a//b'], ['.'], ['..'], ['a/../b'], ['a/./b'], ['a\0b']]) {
    assert.throws(() => selectPaths(paths, []), Error);
  }
  for (const patterns of [null, {}, '*', [1], [''], Array(1), ['!'],
    ['['], ['[]'], ['[!]'], ['a\\'], ['\\a'], ['a\\/b'], ['[\\q]']]) {
    assert.throws(() => selectPaths([], patterns), Error);
  }
  assert.throws(() => selectPaths(['a'], ['*', '[']), Error);
  assert.deepEqual(selectPaths([], []), { selected: [], decisions: [] });
});

const cli = fileURLToPath(new URL('../glob-select.js', import.meta.url));
function run(args) {
  return spawnSync(process.execPath, args, { encoding: 'utf8' });
}

test('CLI output and all failure channels; temporary files live outside workspace', () => {
  const directory = mkdtempSync(join(tmpdir(), 'glob-select-'));
  try {
    const file = join(directory, 'input.json');
    const input = { paths: ['a.js', 'x/b.js'], patterns: ['*.js'], extra: true };
    writeFileSync(file, JSON.stringify(input));
    const success = run([cli, file]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, JSON.stringify(selectPaths(input.paths, input.patterns)) + '\n');
    function fails(args) {
      const result = run(args);
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.length > 0);
    }
    fails([cli]);
    fails([cli, file, file]);
    fails([cli, join(directory, 'missing')]);
    fails([cli, directory]);
    for (const content of ['{', 'null', '[]', '1', '{}', '{"paths":[],"patterns":["["]}']) {
      writeFileSync(file, content);
      fails([cli, file]);
    }
    const imported = run(['--input-type=module', '-e',
      `await import(${JSON.stringify(new URL('../glob-select.js', import.meta.url).href)})`]);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

